<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_customers');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM customers WHERE id=?');$st->execute([$id]);$c=$st->fetch();if(!$c)exit('Customer not found');$err='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$name=trim($_POST['name']??'');if($name==='')throw new Exception('Customer name required.');$code=trim($_POST['customer_code']??'');if($code==='')$code=$c['customer_code']?:('CUS-'.date('ymdHis').random_int(10,99));$state=trim($_POST['state_code']??'');if($state!==''&&!preg_match('/^\d{2}$/',$state))throw new Exception('State Code must be exactly 2 digits.');$tier=is_super_admin()?($_POST['price_tier']??$c['price_tier']):$c['price_tier'];if(!in_array($tier,['retail','wholesale','dealer','offer'],true))$tier='retail';$limit=is_super_admin()?max(0,(float)($_POST['credit_limit']??$c['credit_limit'])):(float)$c['credit_limit'];$active=is_super_admin()?(isset($_POST['active'])?1:0):(int)$c['active'];$st=db()->prepare('UPDATE customers SET customer_code=?,name=?,mobile=?,gstin=?,address=?,state_code=?,price_tier=?,credit_limit=?,active=? WHERE id=?');$st->execute([$code,$name,trim($_POST['mobile']??''),strtoupper(trim($_POST['gstin']??'')),trim($_POST['address']??''),$state,$tier,$limit,$active,$id]);audit('CUSTOMER_UPDATE','customer',$id,['tier'=>$tier,'credit_limit'=>$limit]);$msg='Customer updated.';$st=db()->prepare('SELECT * FROM customers WHERE id=?');$st->execute([$id]);$c=$st->fetch();}catch(Throwable $e){$err=$e->getMessage();}}
page_header('Edit Customer');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row3"><div><label>Customer Code</label><input name="customer_code" value="<?=e($c['customer_code'])?>"></div><div><label>Name</label><input name="name" value="<?=e($c['name'])?>" required></div><div><label>Mobile</label><input name="mobile" value="<?=e($c['mobile'])?>"></div></div><br><div class="row3"><div><label>GSTIN</label><input name="gstin" value="<?=e($c['gstin'])?>"></div><div><label>State Code</label><input name="state_code" maxlength="2" value="<?=e($c['state_code'])?>"></div><div><?php if(is_super_admin()):?><label>Price Tier</label><select name="price_tier"><?php foreach(['retail','wholesale','dealer','offer'] as $t):?><option value="<?=$t?>" <?=$c['price_tier']===$t?'selected':''?>><?=ucfirst($t)?></option><?php endforeach;?></select><?php else:?><label>Price Tier</label><input value="<?=e(strtoupper($c['price_tier']))?> · Admin only" readonly><?php endif;?></div></div><br><div class="row"><div><?php if(is_super_admin()):?><label>Credit Limit</label><input type="number" min="0" step="0.01" name="credit_limit" value="<?=e($c['credit_limit'])?>"><br><br><label><input type="checkbox" name="active" value="1" style="width:auto" <?=$c['active']?'checked':''?>> Active</label><?php else:?><label>Credit Limit</label><input value="₹<?=e(number_format($c['credit_limit'],2))?> · Admin only" readonly><?php endif;?></div><div><label>Address</label><textarea name="address" rows="4"><?=e($c['address'])?></textarea></div></div><br><button class="btn">Save Customer</button></form><?php page_footer();
